      <h2>Add or replace a document</h2>
      <input id="title" placeholder="Title, e.g. Price list" maxlength="120">
      <textarea id="text" placeholder="Paste the text. Same title = replaces the old version." style="margin-top:8px"></textarea>
      <button id="addBtn" style="margin-top:10px;width:100%">Add to the bot</button>
      <div id="msg"></div>
    </div>
  </aside>
