<script>
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LABEL = { answered:'Answered from sources', said_dont_know:"Said I don't know", no_match:'Nothing relevant found', needs_review:'Needs checking', ai_error:'AI error, played safe' };
const GRADE = { correct:'Correct', correct_dont_know:"Correctly said I don't know", wrong:'Wrong', missed:'Missed (answer was there)', made_up:'MADE UP' };

async function api(path, body) {
  const r = await fetch('/webhook/' + path, body === undefined ? {} :
    { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(body) });
  return r.json();
}

function addQ(text) {
  $('#chatEmpty')?.remove();
  const d = document.createElement('div'); d.className = 'q'; d.textContent = text; $('#chat').append(d);
  const a = document.createElement('div'); a.className = 'a'; a.innerHTML = '<div class="bubble thinking">Looking it up…</div>';
  $('#chat').append(a); $('#chat').scrollTop = 1e9; return a;
}
function fillA(el, r) {
  el.className = 'a' + (r.answered ? '' : ' dk') + (r.status === 'needs_review' ? ' rv' : '');
  const srcs = (r.sources || []).map(s =>
    `<details><summary>[${s.n}] ${esc(s.title)} · match ${s.score}</summary><div class="srcbox">${esc(s.text)}</div></details>`).join('');
  el.innerHTML = `<div class="bubble">${esc(r.answer)}</div>
    <div class="meta"><span class="tag t-${r.status}">${LABEL[r.status] || r.status}</span>
    <span class="src">best match ${r.top ?? 0}</span></div>
    ${(r.flags || []).map(f => `<div class="flag">⚠ ${esc(f)}</div>`).join('')}${srcs}`;
  $('#chat').scrollTop = 1e9;
}

async function ask(q) {
  q = q.trim(); if (!q) return;
  $('#question').value = ''; $('#askBtn').disabled = true;
  const el = addQ(q);
  try { const r = await api('kb-ask', { question: q });
        if (r.ok === false) el.innerHTML = `<div class="bubble">${esc(r.problems.join(' '))}</div>`; else fillA(el, r); }
  catch (e) { el.innerHTML = '<div class="bubble">Could not reach the bot. Is n8n running?</div>'; }
  $('#askBtn').disabled = false; $('#question').focus();
}
$('#askForm').onsubmit = e => { e.preventDefault(); ask($('#question').value); };
document.querySelectorAll('[data-q]').forEach(b => b.onclick = () => ask(b.dataset.q));

function showDocs(docs) {
  const names = Object.keys(docs || {});
  $('#docs').innerHTML = names.length ? names.map(n =>
    `<li>${esc(n)}<span>${docs[n].chunks} chunks · ${docs[n].chars} chars</span></li>`).join('')
